/**
 * Minimal, test-verified fixes to the shell scripts generated by
 * `@bomb.sh/tab` 0.0.22. Each fix replaces one exact snippet; if Tab's output
 * changes, `patchScript()` throws instead of silently shipping a half-patched
 * script (and `test/scripts.test.ts` fails). Drop a fix once Tab ships it.
 *
 * fish and powershell scripts are passed through unchanged (not exercised here).
 */

import type { Shell } from "./tab.ts";

interface Fix {
  readonly why: string;
  readonly from: string;
  readonly to: string;
}

const bash: readonly Fix[] = [
  {
    why: "Register with -o default so an empty reply falls back to the shell's own path completion; NoFileComp still turns it off via `compopt +o default`.",
    from: "complete -F __PROGRAM_complete PROGRAM",
    to: "complete -o default -F __PROGRAM_complete PROGRAM",
  },
  {
    why: "FilterFileExt built the glob `\\.(|png)`, which matches nothing and dropped directories; use bash-completion's _filedir (the script already requires bash-completion).",
    from: `        local filter=""
        for ext in $out; do
            filter="$filter|$ext"
        done
        filter="\\.($filter)"
        compopt -o filenames
        COMPREPLY=( $(compgen -f -X "!$filter" -- "$cur") )
        return`,
    to: `        local filter="" ext
        for ext in $out; do
            filter="\${filter:+$filter|}$ext"
        done
        _filedir "$filter"
        return`,
  },
  {
    why: "FilterDirs word-split directory names containing spaces.",
    from: `        compopt -o dirnames
        COMPREPLY=( $(compgen -d -- "$cur") )
        return`,
    to: `        _filedir -d
        return`,
  },
  {
    why: "For `--opt=value`, readline replaces only the text after `=`, but candidates were matched against the whole word, so nothing matched.",
    from: `    COMPREPLY=( $(compgen -W "\${completions[*]}" -- "$cur") )`,
    to: `    local word="$cur"
    [[ "$word" == -*=* ]] && word="\${word#*=}"
    COMPREPLY=( $(compgen -W "\${completions[*]}" -- "$word") )`,
  },
];

const zsh: readonly Fix[] = [
  {
    why: "`${=words}` re-split words on whitespace, so `my\\ file.png` reached the CLI as two words and shifted positional counting.",
    from: `    words=( "\${=words[1,CURRENT]}" )`,
    to: `    words=( "\${(@)words[1,CURRENT]}" )`,
  },
  {
    why: "Words were (q)-quoted while still carrying the user's shell quoting, so the CLI received backslashes and quotes literally. Unquote with (Q) first; the result is also never re-expanded by eval.",
    from: `    local quoted_args=("\${(@q)args_to_quote}")`,
    to: `    local -a unquoted_args=("\${(@Q)args_to_quote}")
    local quoted_args=("\${(@q)unquoted_args}")`,
  },
  {
    why: "The colon escape produced `:` instead of `\\:`, so a value containing `:` was split into value and description by _describe.",
    from: "            comp=${comp//:/\\:}",
    to: "            comp=${comp//:/\\\\:}",
  },
];

const fixes: Readonly<Record<Shell, readonly Fix[]>> = { bash, zsh, fish: [], powershell: [] };

export function patchScript(shell: Shell, program: string, script: string): string {
  // Tab derives bash function names from the program name this way.
  const identifier = program.replace(/[-:]/g, "_");
  return fixes[shell].reduce((text, fix) => {
    const from = fix.from.replaceAll("__PROGRAM_", `__${identifier}_`).replaceAll(" PROGRAM", ` ${program}`);
    const to = fix.to.replaceAll("__PROGRAM_", `__${identifier}_`).replaceAll(" PROGRAM", ` ${program}`);
    if (!text.includes(from)) {
      throw new Error(
        `The ${shell} script generated by @bomb.sh/tab changed; review src/kit/scripts.ts (${fix.why})`,
      );
    }
    return text.replace(from, to);
  }, script);
}
